class Team:
    def __init__(self, name):
        self.name = name
        self.members = []

    def add(self, person):
        self.members.append(person)


def build_teams(assignments):
    teams = {}
    for person, team_name in assignments:
        if team_name not in teams:
            teams[team_name] = Team(team_name)
        teams[team_name].add(person)
    return {name: team.members for name, team in teams.items()}
